from pathlib import Path
import re

path = Path(__file__).parent / "garden" / "static" / "app.js"
text = path.read_text(encoding="utf-8")

week = r'''function goalFeedbackKindForItem(item){if(!item)return'exercise';if(item.course_id)return item.input_state==='awaiting_course_progress'?'course':(/证明|复述/.test(item.title||'')?'proof':'exercise');if(item.track_code==='amss_exam')return'mock';if(item.track_code==='ergodic')return/讲解/.test(item.title||'')?'talk':/问题/.test(item.title||'')?'reading':'reading';if(item.track_code==='algebra')return/口头/.test(item.title||'')?'oral':'exercise';return'exercise'}
function openGoalFeedback(itemId='',kind='',course=''){goalView('evidence');const data=state.goal.data||{},items=data.current_week?.items||[],item=items.find(value=>value.id===itemId);const select=$('#goalFeedbackItem');if(select)select.value=itemId||'';if(item)$('#goalFeedbackTrack').value=item.track_id||'';const type=$('#goalFeedbackType');if(type)type.value=kind||goalFeedbackKindForItem(item);goalQuickCourse=course||item?.course_id&&((data.course_profiles||[]).find(profile=>profile.id===item.course_id)?.name)||'';renderGoalQuickForm(data);requestAnimationFrame(()=>$('#goal-view-evidence')?.scrollIntoView({behavior:'smooth',block:'start'}))}
function renderGoalWeek(data){if(window.renderCourseSchedule&&data.course_schedule)window.renderCourseSchedule($("#goalCourseSchedule"),data.course_schedule);const items=data.current_week?.items||[];$('#goalWeekList').innerHTML=items.length?items.map(item=>{const inputLabel=goalInputLabels[item.input_state]||item.input_state||'待核验';const sync=item.sync_status?` · ${item.sync_status==='queued'?'等待 Obsidian 写回':item.sync_status==='synced'?'已同步任务':'任务已完成'}`:'';const disabled=item.task_id||item.status==='completed'||item.input_state!=='ready';const action=item.task_id?'已进入任务系统':item.status==='completed'?'已完成':item.input_state!=='ready'?inputLabel:'确认这一天';return`<article class="pixel-panel goal-week-item ${item.input_state!=='ready'?'is-waiting':''}"><div><p class="eyebrow">${escapeHtml(item.track_title||item.track_code||'TRACK')}</p><h3>${escapeHtml(item.title)}</h3><div class="goal-week-meta"><span>${goalMinutes(item.deep_minutes)}</span><span>${goalStatusLabels[item.status]||item.status}</span><span>${escapeHtml(inputLabel)}</span><span>推荐 ${goalDate(item.recommended_date)}</span>${item.accepted_date?`<span>已确认 ${goalDate(item.accepted_date)}</span>`:''}</div><p>${escapeHtml(item.description||'')}${escapeHtml(sync)}</p></div><div class="goal-day-action"><button type="button" class="goal-feedback-action" data-goal-feedback="${escapeHtml(item.id)}">记进度</button><input type="date" value="${escapeHtml(item.accepted_date||item.recommended_date||'')}" data-goal-date="${escapeHtml(item.id)}" ${disabled?'disabled':''}><button type="button" data-goal-accept="${escapeHtml(item.id)}" ${disabled?'disabled':''}>${escapeHtml(action)}</button></div></article>`}).join(''):'<article class="pixel-panel goal-section-head"><p>当前没有周任务；请先完整复盘或等待下一个计划周。</p></article>';$$('[data-goal-accept]').forEach(button=>button.onclick=()=>acceptGoalDay(button.dataset.goalAccept,button));$$('[data-goal-feedback]').forEach(button=>button.onclick=()=>openGoalFeedback(button.dataset.goalFeedback))}'''
text, count = re.subn(r"function renderGoalWeek\(data\).*?(?=\nfunction renderGoalRoute)", week, text, flags=re.S)
assert count == 1, count

course_profile = r'''function renderGoalCourseProfiles(data){const progress=data.course_progress?.by_course||{};$('#goalCourseProfileGrid').innerHTML=(data.course_profiles||[]).map(profile=>{const p=progress[profile.name]||{},distribution=p.mastery_distribution||{};const status=profile.confirmation_status==='confirmed'?'已确认':'部分确认';return`<article class="pixel-panel goal-course-profile"><div class="goal-course-profile-head"><div><p class="eyebrow">${escapeHtml(profile.course_code||'COURSE')}</p><h3>${escapeHtml(profile.name)}</h3></div><span>${status}</span></div><p>${escapeHtml(profile.teacher||'教师待核验')} · ${escapeHtml((profile.textbooks||[])[0]||'教材待核验')}</p><p>${escapeHtml(goalAssessmentText(profile.assessment_weights))}</p><div class="goal-course-mastery"><span>授课小节<b>${p.confirmed_taught_units||0}/${p.total_units||0}</b></span><span>掌握 2<b>${distribution['2']||0}</b></span><span>掌握 3<b>${distribution['3']||0}</b></span><span>考试日期<b>${profile.exam_date?goalDate(profile.exam_date):'未知'}</b></span></div>${profile.hours_warning?`<p class="goal-course-warning">${escapeHtml(profile.hours_warning)}</p>`:''}<button type="button" class="goal-course-record" data-goal-course-record="${escapeHtml(profile.name)}">记录上课</button></article>`}).join('');$$('[data-goal-course-record]').forEach(button=>button.onclick=()=>openGoalFeedback('','course',button.dataset.goalCourseRecord))}'''
text, count = re.subn(r"function renderGoalCourseProfiles\(data\).*?(?=\nfunction renderGoalCourseUnitPicker)", course_profile, text, flags=re.S)
assert count == 1, count

quick = r'''let goalQuickChoices={},goalQuickCourse='';
const goalQuickOptions={result:[['done','完成'],['partial','完成一部分'],['blocked','卡住']],assistance:[['none','全程独立'],['hint','用了提示'],['solution','看了解答'],['mixed','各题不同'],['unknown','未记录']],verification:[['reference','对照解答'],['human','他人核对'],['self','自己判断'],['unchecked','未核对']],basis:[['lecture','听课感受'],['recall','合书回忆'],['practice','题目 / 证明检验'],['unknown','暂不评估']],error:[['concept','概念 / 条件'],['strategy','没找到思路'],['proof','推导 / 证明'],['calculation','计算失误'],['unknown','暂不清楚']]};
function goalQuickButtons(key,items){return`<div class="goal-quick-options" data-goal-quick-group="${key}">${items.map(item=>`<button type="button" data-goal-quick-choice="${key}" data-value="${item[0]}" aria-pressed="${goalQuickChoices[key]===item[0]?'true':'false'}">${escapeHtml(item[1])}</button>`).join('')}</div>`}
function goalQuickGroup(label,key,items){return`<fieldset><legend>${escapeHtml(label)}</legend>${goalQuickButtons(key,items)}</fieldset>`}
function goalQuickNumber(id,label,placeholder='',max=10000){return`<label>${escapeHtml(label)}<input id="${id}" type="number" inputmode="decimal" min="0" max="${max}" step="any" placeholder="${escapeHtml(placeholder)}"></label>`}
function goalQuickValue(id){const element=$(`#${id}`);return element&&element.value!==''?element.value:null}
function renderGoalCourseUnitPicker(data){const course=$('#goalFeedbackCourse')?.value||goalQuickCourse,progress=data.course_progress?.by_course?.[course],root=$('#goalCourseUnitPicker');if(!root)return;if(!course||!progress){root.innerHTML='<p class="setting-help">先选择课程。</p>';return}const groups=new Map();(progress.units||[]).forEach(unit=>{const key=`${unit.chapter_no}. ${unit.chapter_title}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(unit)});root.innerHTML=[...groups.entries()].map(([chapter,units],index)=>`<details ${index===0?'open':''}><summary>${escapeHtml(chapter)}</summary><div class="goal-course-unit-group">${units.map(unit=>`<label class="goal-course-unit"><input type="checkbox" data-goal-course-unit="${escapeHtml(unit.id)}"><span>${escapeHtml(`${unit.chapter_no}.${unit.section_no} ${unit.title}`)}</span><select data-goal-course-mastery="${escapeHtml(unit.id)}" disabled>${Object.entries(goalMasteryLabels).map(([level,label])=>`<option value="${level}">${escapeHtml(label)}</option>`).join('')}</select></label>`).join('')}</div></details>`).join('');$$('[data-goal-course-unit]').forEach(box=>box.onchange=()=>{const select=$(`[data-goal-course-mastery="${CSS.escape(box.dataset.goalCourseUnit)}"]`);if(select)select.disabled=!box.checked})}
function goalQuickCourses(data){return`<label>课程<select id="goalFeedbackCourse"><option value="">请选择</option>${(data.course_profiles||[]).map(profile=>`<option value="${escapeHtml(profile.name)}" ${profile.name===goalQuickCourse?'selected':''}>${escapeHtml(profile.name)}</option>`).join('')}</select></label>`}
function renderGoalQuickAdaptive(){const root=$('#goalQuickAdaptive'),kind=$('#goalFeedbackType').value;let html='';if(kind==='exercise'&&['hint','solution','mixed'].includes(goalQuickChoices.assistance))html=`<p class="eyebrow">ONE DECISIVE FOLLOW-UP</p>${goalQuickNumber('goalQuickIndependent','其中独立做对几题？','无法区分可留空')}`;else if(kind==='exercise'&&goalQuickChoices.assistance==='none'&&goalQuickValue('goalQuickCorrect')!==null&&Number(goalQuickValue('goalQuickCorrect'))<Number(goalQuickValue('goalQuickAttempted')))html=`<p class="eyebrow">ONE DECISIVE FOLLOW-UP</p>${goalQuickGroup('这次最主要的失误','diagnostic',goalQuickOptions.error)}`;else if(kind==='proof'&&goalQuickChoices.proof_result&&goalQuickChoices.proof_result!=='independent')html=`<p class="eyebrow">ONE DECISIVE FOLLOW-UP</p>${goalQuickGroup('最需要补的环节','diagnostic',[['hypothesis','理解假设'],['construction','关键构造'],['deduction','推导细节'],['boundary','边界 / 反例'],['unknown','不确定']])}`;root.innerHTML=html;root.classList.toggle('hidden',!html);bindGoalQuickChoices(root)}
function bindGoalQuickChoices(scope=document){scope.querySelectorAll('[data-goal-quick-choice]').forEach(button=>button.onclick=()=>{const key=button.dataset.goalQuickChoice;goalQuickChoices[key]=button.dataset.value;scope.querySelectorAll(`[data-goal-quick-choice="${CSS.escape(key)}"]`).forEach(peer=>peer.setAttribute('aria-pressed',String(peer===button)));if(key==='common_mastery'){$$('[data-goal-course-unit]:checked').forEach(box=>{const select=$(`[data-goal-course-mastery="${CSS.escape(box.dataset.goalCourseUnit)}"]`);if(select)select.value=button.dataset.value})}if(['assistance','proof_result'].includes(key))renderGoalQuickAdaptive()})}
function renderGoalQuickForm(data){goalQuickChoices={};const kind=$('#goalFeedbackType').value,root=$('#goalQuickFields');let html='';if(kind==='course'){html=goalQuickCourses(data)+`<section id="goalCourseProgressFields" class="goal-course-progress-fields"><div><h3>确认实际讲到的小节</h3><p class="setting-help">勾选小节；共同掌握度可一次应用，再按小节改动。</p></div><div id="goalCourseUnitPicker" class="goal-course-unit-picker"></div>${goalQuickGroup('所选小节共同掌握度','common_mastery',Object.entries(goalMasteryLabels))}${goalQuickGroup('这次掌握度依据','basis',goalQuickOptions.basis)}</section>`}else if(kind==='exercise'){html=`<div class="goal-form-grid">${goalQuickNumber('goalQuickAttempted','尝试题数','例如 10')}${goalQuickNumber('goalQuickCorrect','最终做对','未核对可留空')}</div>${goalQuickGroup('完成情况','result',goalQuickOptions.result)}${goalQuickGroup('解题时用了多少帮助？','assistance',goalQuickOptions.assistance)}${goalQuickGroup('正确数怎么核对？','verification',goalQuickOptions.verification)}<label>题组 / 来源（可选）<input id="goalQuickSource" maxlength="160" placeholder="如：作业1第1–10题"></label>`}else if(kind==='proof'){html=`${goalQuickGroup('这次能做到','proof_result',[['independent','独立完成'],['hinted','提示后完成'],['partial','只完成一部分'],['blocked','尚未完成']])}${goalQuickGroup('本次属于','attempt_timing',[['first','首次尝试'],['immediate','即时重做'],['delayed','隔日复测'],['unknown','不确定']])}${goalQuickGroup('怎么核对？','verification',goalQuickOptions.verification)}<label>命题 / 证明对象<input id="goalQuickObject" maxlength="200" placeholder="自动关联不准确时补充"></label>`}else if(kind==='grade'){html=`${goalQuickCourses(data)}<label>考核项目<input id="goalQuickComponent" maxlength="100" placeholder="如：第一次作业"></label><div class="goal-form-grid">${goalQuickNumber('goalQuickScore','得分','真实值')}${goalQuickNumber('goalQuickMax','满分','例如 100')}</div>${goalQuickGroup('成绩来源','origin',[['official','老师 / 教务公布'],['self','对照标准自评'],['estimate','暂时估分']])}` }else if(kind==='mock'){html=`<label>真实题源 / 试卷 ID<input id="goalQuickSource" maxlength="160" placeholder="不同卷必须使用不同 ID"></label><div class="goal-form-grid">${goalQuickNumber('goalQuickScore','得分','未批改可留空',150)}${goalQuickNumber('goalQuickMax','满分','例如 150',150)}${goalQuickNumber('goalQuickElapsed','实际用时（分钟）','例如 120',1440)}</div>${goalQuickGroup('完成条件','condition',[['timed','完整限时'],['interrupted','有中断'],['untimed','非限时'],['unknown','未记录']])}${goalQuickGroup('题目熟悉度','novelty',[['new','首次见'],['repeat','做过 / 看过'],['mixed','部分见过'],['unknown','不确定']])}${goalQuickGroup('评分依据','verification',goalQuickOptions.verification)}` }else if(kind==='reading'){html=`${goalQuickGroup('本次进展','result',goalQuickOptions.result)}${goalQuickGroup('实际检验到哪一步？','quality',[['summary','能合书讲主线'],['proof','能重建关键证明'],['apply','能用于新例子'],['untested','还没有检验']])}${goalQuickNumber('goalQuickUnits','新增笔记页数（可选）','未统计可留空')}` }else if(kind==='talk'){html=`${goalQuickNumber('goalQuickUnits','实际讲解分钟','例如 20',1440)}${goalQuickGroup('讲解情况','talk_result',[['independent','连贯讲完'],['notes','频繁看笔记'],['blocked','没有讲完']])}${goalQuickGroup('追问表现','questions',[['independent','独立答出'],['hinted','提示后答出'],['failed','没有答出'],['untested','没有追问']])}${goalQuickGroup('评价者','rater',[['self','自己'],['peer','同学 / 老师'],['unknown','未评价']])}` }else if(kind==='oral'){html=`<p class="setting-help">四项 0–5；未测请选择“—”。</p><div class="goal-oral-grid">${['定义','例子','策略','追问'].map((label,index)=>`<label>${label}<select data-goal-oral="${index}"><option value="">—</option>${[0,1,2,3,4,5].map(value=>`<option value="${value}">${value}</option>`).join('')}</select></label>`).join('')}</div>${goalQuickGroup('评分者','rater',[['self','自己'],['peer','同学 / 老师'],['ai','AI 辅助']])}${goalQuickGroup('回答条件','assistance',[['none','独立回答'],['hint','有提示'],['solution','看了材料'],['unknown','未记录']])}` }else{html=`${goalQuickGroup('主要原因','blocked_reason',[['concept','概念不清'],['proof','证明卡住'],['material','缺资料'],['time','时间不足'],['other','其他']])}${goalQuickGroup('影响范围','impact',[['local','一个步骤'],['session','本次做不下去'],['recurring','多次反复'],['unknown','不确定']])}${goalQuickGroup('希望怎么处理','request',[['split','拆小任务'],['explain','补解释 / 前置'],['defer','重新建议日期']])}` }root.innerHTML=html;bindGoalQuickChoices(root);$('#goalFeedbackCourse')?.addEventListener('change',event=>{goalQuickCourse=event.target.value;renderGoalCourseUnitPicker(data)});if(kind==='course')renderGoalCourseUnitPicker(data);root.querySelectorAll('input').forEach(input=>input.addEventListener('input',renderGoalQuickAdaptive));renderGoalQuickAdaptive()}
function renderGoalEvidence(data){const items=data.current_week?.items||[];renderGoalCourseProfiles(data);const itemSelect=$('#goalFeedbackItem'),selectedItem=itemSelect.value;itemSelect.innerHTML='<option value="">不关联具体任务</option>'+items.map(item=>`<option value="${escapeHtml(item.id)}" data-track="${escapeHtml(item.track_id)}">${escapeHtml(item.title)}</option>`).join('');if(selectedItem&&items.some(item=>item.id===selectedItem))itemSelect.value=selectedItem;const selected=items.find(item=>item.id===itemSelect.value);$('#goalFeedbackTrack').value=selected?.track_id||$('#goalFeedbackTrack').value||'track-courses';const materials=data.materials||{};$('#goalMaterialGaps').innerHTML=`<div class="goal-mini-list">${(materials.gaps||[]).map(gap=>`<p>${escapeHtml(gap)}</p>`).join('')||'<p>暂无资料缺口。</p>'}<p>授权入口：${escapeHtml(materials.manifest_path||'目标模式资料清单.md')}</p></div>`;$('#goalMaterialDocs').innerHTML=`<div class="goal-mini-list">${(materials.documents||[]).map(doc=>{const meta=doc.metadata||{},kind=meta.note_format==='mathink_markdown'?'MathInk 可见层':meta.note_format||'';return`<p><b>${escapeHtml(doc.title)}</b><br>${doc.page_count||'—'} 页 · ${escapeHtml(doc.status||'')} ${kind?`· ${escapeHtml(kind)}`:''}</p>`}).join('')||'<p>尚未索引授权资料；勾选清单后由 Windows 导出器分页提取。</p>'}</div>`;$('#goalSources').innerHTML=`<div class="goal-mini-list">${(data.sources||[]).map(source=>source.url?`<a href="${escapeHtml(source.url)}" target="_blank" rel="noopener"><b>${escapeHtml(source.grade)}</b> · ${escapeHtml(source.title)}${source.reference_only?'（往届参考）':''}</a>`:`<p>${escapeHtml(source.title)}</p>`).join('')}</div>`;renderGoalQuickForm(data)}'''
text, count = re.subn(r"function renderGoalCourseUnitPicker\(data\).*?(?=\nfunction renderGoalChat)", quick, text, flags=re.S)
assert count == 1, count

submit = r'''function goalQuickRequired(kind,keys){const missing=keys.find(key=>!goalQuickChoices[key]);if(missing){toast('请补选本次表现条件；未知可以明确选择。',true);return false}return true}
async function submitGoalFeedback(){const button=$('#goalFeedbackSubmit'),kind=$('#goalFeedbackType').value,itemId=$('#goalFeedbackItem').value||null,item=(state.goal.data?.current_week?.items||[]).find(value=>value.id===itemId),trackId=item?.track_id||$('#goalFeedbackTrack').value||'track-courses';let evidenceType='progress_update',score=null,maxScore=null,completedUnits=null,sourceId=null,blockedReason=null;const details={feedback_schema_version:2,feedback_kind:kind,performance:{},conditions:{},note:$('#goalFeedbackNote').value.trim()||null};if(kind==='course'){evidenceType='course_progress';const course=$('#goalFeedbackCourse').value,selected=$$('[data-goal-course-unit]:checked');if(!course||!selected.length||!goalQuickRequired(kind,['common_mastery','basis'])){if(!course||!selected.length)toast('请选择课程和实际讲到的小节。',true);return}details.course=course;details.taught_units=selected.map(box=>({unit_id:box.dataset.goalCourseUnit,mastery:Number($(`[data-goal-course-mastery="${CSS.escape(box.dataset.goalCourseUnit)}"]`).value)}));details.conditions.mastery_basis=goalQuickChoices.basis}else if(kind==='exercise'){if(!goalQuickRequired(kind,['result','assistance','verification']))return;const attempted=Number(goalQuickValue('goalQuickAttempted')),correctRaw=goalQuickValue('goalQuickCorrect'),correct=correctRaw===null?null:Number(correctRaw),independentRaw=goalQuickValue('goalQuickIndependent'),independent=independentRaw===null?null:Number(independentRaw);if(!Number.isInteger(attempted)||attempted<0||correct!==null&&(!Number.isInteger(correct)||correct<0||correct>attempted)||independent!==null&&(!Number.isInteger(independent)||independent<0||correct===null||independent>correct)){toast('请检查题数：独立做对 ≤ 最终做对 ≤ 尝试数。',true);return}evidenceType=item?.track_code==='algebra'?'algebra_written':'progress_update';details.performance={attempted,correct,independent_correct:goalQuickChoices.assistance==='none'?correct:independent,result:goalQuickChoices.result,error_type:goalQuickChoices.diagnostic||null};details.conditions={assistance:goalQuickChoices.assistance,verification:goalQuickChoices.verification};completedUnits=attempted;sourceId=goalQuickValue('goalQuickSource')}else if(kind==='proof'){if(!goalQuickRequired(kind,['proof_result','attempt_timing','verification']))return;details.performance={result:goalQuickChoices.proof_result,weak_step:goalQuickChoices.diagnostic||null,object:goalQuickValue('goalQuickObject')};details.conditions={attempt_timing:goalQuickChoices.attempt_timing,verification:goalQuickChoices.verification}}else if(kind==='grade'){if(!goalQuickRequired(kind,['origin']))return;evidenceType='course_component';score=Number(goalQuickValue('goalQuickScore'));maxScore=Number(goalQuickValue('goalQuickMax'));if(!Number.isFinite(score)||!Number.isFinite(maxScore)||maxScore<=0||score<0||score>maxScore){toast('请填写有效得分和满分。',true);return}details.course=$('#goalFeedbackCourse').value;details.component=goalQuickValue('goalQuickComponent');details.conditions={origin:goalQuickChoices.origin}}else if(kind==='mock'){if(!goalQuickRequired(kind,['condition','novelty','verification']))return;evidenceType='exam_mock';sourceId=goalQuickValue('goalQuickSource');if(!sourceId){toast('请选择或填写真实题源。',true);return}const scoreRaw=goalQuickValue('goalQuickScore'),maxRaw=goalQuickValue('goalQuickMax');score=scoreRaw===null?null:Number(scoreRaw);maxScore=maxRaw===null?null:Number(maxRaw);details.performance={elapsed_minutes:goalQuickValue('goalQuickElapsed')===null?null:Number(goalQuickValue('goalQuickElapsed'))};details.conditions={completion:goalQuickChoices.condition,novelty:goalQuickChoices.novelty,verification:goalQuickChoices.verification}}else if(kind==='reading'){if(!goalQuickRequired(kind,['result','quality']))return;evidenceType='ergodic_note';completedUnits=goalQuickValue('goalQuickUnits')===null?null:Number(goalQuickValue('goalQuickUnits'));details.performance={result:goalQuickChoices.result,quality_check:goalQuickChoices.quality}}else if(kind==='talk'){if(!goalQuickRequired(kind,['talk_result','questions','rater']))return;evidenceType='ergodic_talk';completedUnits=Number(goalQuickValue('goalQuickUnits'));if(!Number.isFinite(completedUnits)){toast('请填写实际讲解分钟。',true);return}details.performance={result:goalQuickChoices.talk_result,questions:goalQuickChoices.questions};details.conditions={rater:goalQuickChoices.rater}}else if(kind==='oral'){if(!goalQuickRequired(kind,['rater','assistance']))return;evidenceType='algebra_oral';const values=$$('[data-goal-oral]').map(select=>select.value===''?null:Number(select.value));details.oral_scores={definition:values[0],example:values[1],strategy:values[2],follow_up:values[3]};details.conditions={rater:goalQuickChoices.rater,assistance:goalQuickChoices.assistance}}else{if(!goalQuickRequired(kind,['blocked_reason','impact','request']))return;blockedReason=goalQuickChoices.blocked_reason;details.performance={impact:goalQuickChoices.impact};details.conditions={requested_response:goalQuickChoices.request}}const body={track_id:trackId,plan_item_id:itemId,evidence_type:evidenceType,deep_minutes:optionalNumber('#goalFeedbackMinutes'),status:$('#goalFeedbackStatus').value||null,score,max_score:maxScore,completed_units:completedUnits,source_id:sourceId,blocked_reason:blockedReason,details};button.disabled=true;try{const result=await goalWrite('/api/goal-agent/feedback',body,'feedback');const boundary=result.evidence_boundary||'证据已按原始条件保存；不足的部分保持待核验。';$('#goalEvidenceBoundary').textContent=boundary;toast('反馈已保存；AI 复盘将结合历史与资料，不会把单次自评当成完整结论');$('#goalFeedbackNote').value='';await loadGoalMode()}catch(error){toast(error.message,true)}finally{button.disabled=false}}'''
text, count = re.subn(r"function optionalNumber\(selector\).*?(?=\nasync function sendGoalChat)", "function optionalNumber(selector){const value=$(selector)?.value;return value===''||value===undefined?null:Number(value)}\n" + submit, text, flags=re.S)
assert count == 1, count

text = text.replace("$('#goalFeedbackItem').onchange=event=>{const selected=event.target.selectedOptions[0];if(selected?.dataset.track)$('#goalFeedbackTrack').value=selected.dataset.track};", "$('#goalFeedbackItem').onchange=event=>{const item=(state.goal.data?.current_week?.items||[]).find(value=>value.id===event.target.value);if(item){$('#goalFeedbackTrack').value=item.track_id;$('#goalFeedbackType').value=goalFeedbackKindForItem(item);goalQuickCourse=item.course_id&&((state.goal.data.course_profiles||[]).find(profile=>profile.id===item.course_id)?.name)||''}renderGoalQuickForm(state.goal.data||{})};$('#goalFeedbackType').onchange=()=>renderGoalQuickForm(state.goal.data||{});")
